import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { peopleKey, type Person } from '../people/people';
import { usePersonRowAction } from '../people/rowAction';
import { useShownColumns } from '../columns/columns';

function RetireHead({ user }: { user: string }) {
  const shown = useShownColumns(user);
  return (
    <>
      {shown('retired') && <th>Retired</th>}
      <th>Retired from</th>
      <th>Past retirements</th>
      <th />
    </>
  );
}

/** Whether the person is retired and from when, and the date and button that retire them (a blank date: the sheet's
 *  today). A person with a retirement date counts as retired at once, whatever the date; no claim of theirs may be
 *  dated after it. A retired person can be unretired (on the sheet's today): the retirement is then kept as a past one,
 *  one line each, and no claim of theirs may be dated after its from and before its to. A refused retirement or
 *  unretirement (anyone not retired) shows the row's error. */
function PersonRetire({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const shown = useShownColumns(user);
  const queryClient = useQueryClient();
  const [from, setFrom] = useState('');
  const submit = useSubmitOnce();
  const rowAction = usePersonRowAction(sheetId, person.id, 'retire');
  const unretireAction = usePersonRowAction(sheetId, person.id, 'unretire');
  const retire = useMutation({
    mutationFn: (date: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/retire`, { from: date, by: user }),
    onSuccess: () => {
      setFrom('');
      return queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onSettled: submit.end,
  });
  const unretire = useMutation({
    mutationFn: () =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/unretire`, { by: user }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
    onSettled: submit.end,
  });

  return (
    <>
      {shown('retired') && <td data-testid="person-retired">{person.retiredFrom !== null ? 'yes' : 'no'}</td>}
      <td data-testid="person-retired-from">{person.retiredFrom ?? ''}</td>
      <td>
        {(person.retirements ?? []).map((r, i) => (
          <div key={i} data-testid="person-retirement-line">
            {r.from} to {r.to}
          </div>
        ))}
      </td>
      <td>
        <input
          data-testid="person-retire-date"
          placeholder="yyyy-MM-dd"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            retire.reset();
          }}
        />{' '}
        <button
          type="button"
          data-testid="person-retire"
          disabled={retire.isPending}
          onClick={() => {
            if (!submit.begin()) return;
            rowAction.take();
            retire.reset();
            retire.mutate(from.trim());
          }}
        >
          Retire
        </button>{' '}
        <button
          type="button"
          data-testid="person-unretire"
          disabled={unretire.isPending}
          onClick={() => {
            if (!submit.begin()) return;
            unretireAction.take();
            unretire.reset();
            unretire.mutate();
          }}
        >
          Unretire
        </button>
        {retire.isError && rowAction.isLatest && <span data-testid="person-error"> Could not retire this person.</span>}
        {unretire.isError && unretireAction.isLatest && (
          <span data-testid="person-error"> Could not unretire this person: they are not retired.</span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 40, Component: RetireHead }),
  PersonRow.fill({ order: 40, Component: PersonRetire }),
];
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import type { Person } from '../people/people';
import { useSnapshots } from './snapshots';

function SnapshotsHead() {
  return <th>Snapshots</th>;
}

/** A person's snapshot lines: one per SNAPSHOT written for them, oldest first, as "<the day being left> <due-total>". */
function PersonSnapshots({ sheetId, person }: { sheetId: string; person: Person }) {
  const snapshots = useSnapshots(sheetId);
  const mine = (snapshots.data ?? []).filter((s) => s.personId === person.id);
  return (
    <td>
      {mine.map((s, i) => (
        <div key={i} data-testid="person-snapshot-line">
          {`${s.day} ${s.dueTotal}`}
        </div>
      ))}
    </td>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 95, Component: SnapshotsHead }),
  PersonRow.fill({ order: 95, Component: PersonSnapshots }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { nowKey, useReadNow } from '../../query/readNow';
import { retiredOn, type Person } from '../people/people';

/** A claim's status: DRAFT when added, then OPEN and SETTLED; a clerk settling above the clerk limit makes it PENDING
 *  until a steward approves (SETTLED) or rejects (OPEN) it; a DRAFT, OPEN or PENDING claim may be VOID, as may a SETTLED one
 *  by a steward within 7 days of its settlement; a DRAFT may be DELETED (counting nowhere), and restored to DRAFT on the
 *  sheet-today it was deleted. Opening a claim whose due is above the review threshold on its date makes it REVIEW
 *  (unnumbered, counting nowhere) until a steward reviews it (OPEN); it may only be voided otherwise. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED' | 'REVIEW';

/** A claim of a person. `amount` is text with two decimals (never a float); `date` is yyyy-MM-dd; `number` (text: FY2026-1, FY2026-2, ... (older claims 1, 2, ...), or P1-1, X-1 when numbered per period) is given
 *  when the claim is opened (null for a draft or a voided claim); `due` is the due fixed when it was settled (null
 *  while its due is live, worked out from its grade's current rate); `openedBy` is who opened it (null when never
 *  opened); `stated` is whether its person's last statement bound it to the due as shown, late charge included, `statedDue` (null when it had
 *  none), which it shows while its due is not fixed; `corrects` is, for a correction (a negative amount),
 *  the number of the SETTLED claim of the same person it corrects (null for any other claim); `roundsOn` (yyyy-MM-dd)
 *  is the date that decides how its live figures round: the corrected claim's date for a correction, else its own;
 *  `dueBy` (yyyy-MM-dd) is its due-by, fixed when it was added from the terms in force on that day (its person's own, else their grade's, else the sheet's), or as a steward last set it directly (then kept, whatever holiday is added later);
 *  `deferred` is whether it is deferred on the sheet's today (a claim that counts, deferred until a date after it and
 *  not bound by a statement: it counts in no total, is not overdue and cannot be settled; while bound the deferral
 *  waits for the binding to end) and `deferredUntil` (yyyy-MM-dd) the date it was last deferred until (shown
 *  even once that date has passed; null when never deferred); `proofs` is its proofs count (a claim whose due is above the sheet's proof threshold
 *  on its date cannot be settled nor approved while it is 0); `splitFrom` is the number of the claim it was split from
 *  (null for any other claim); `log` is its status log, oldest first; `lockedBy` is who has its editor open (it is locked for
 *  everyone else; null when no one does). */
export type Claim = {
  id: number;
  sheetId: string;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  roundsOn: string;
  dueBy: string;
  deferred: boolean;
  deferredUntil: string | null;
  /** Whether a steward waived its late charge: from then on it bears none, whatever its overdue state. */
  waived: boolean;
  /** The user a steward last assigned it to for review (null when never): kept once it leaves REVIEW. */
  reviewAssigned: string | null;
  /** Whether it is held (an OPEN or PENDING claim is held and released with Hold): a held claim still counts in every
   *  total, as one dated within a hold of its person does. */
  held: boolean;
  proofs: number;
  /** How many of its proofs are receipts (the kind when none is chosen) and photos. */
  proofsReceipt: number;
  proofsPhoto: number;
  splitFrom: string | null;
  log: ClaimLogLine[];
  lockedBy: string | null;
  /** Whether it was added while the period its date falls in was soft-closed. */
  lateEntry: boolean;
  /** The last day (yyyy-MM-dd) a reminder was written for it; null when never reminded. */
  reminded: string | null;
  /** Its external reference (surrounding spaces removed; no two claims of a sheet share one, case ignored); null when none. */
  ref: string | null;
  /** Its tags: each trimmed and in lower case, no repeats, sorted; empty when none. */
  tags: string[];
  /** Its comments, in the order written. */
  comments: ClaimComment[];
  /** The number of the bulk settle batch that settled it; null when none did (settled one at a time, or not settled). */
  batch: number | null;
  /** Its lines, in the order added; with any, its amount is their quantities times unit amounts added up. */
  lines: ClaimLine[];
  /** The order it was added in, across every sheet: a forward-only rate applies only to claims whose seq is above its
   *  `after` (see claimRate); absent for a claim not yet added. */
  seq?: number;
  /** The shares of it other people of the sheet hold, in the order made: each holder's person id and share (a percent,
   *  two decimals). Each holder's part of its due counts in their figures instead of its own person's (see shareParts). */
  shares?: ClaimShare[];
};

